  'group-edit':()=>`${H.crumb(['אנשים','קבוצות','הנהלה'])}${head('קבוצת הנהלה','שינוי הדלתות ישפיע על חברי הקבוצה.',btn('סקירת השינוי','group-review','primary','arrow'))}<div class="columns"><section class="card"><div class="form-section"><h3>פרטי הקבוצה</h3>${field('שם הקבוצה','הנהלה')}</div><div class="form-section"><h3>דלתות מורשות לקבוצה</h3><div class="check-grid">${DEMO.doors.map((n,i)=>check(`${icon('door')} ${n}`,i<7)).join('')}</div></div><div class="form-footer"><small>לפי התחנות שנבחרו. חריגות אישיות לא יימחקו.</small>${btn('ביטול','groups')}${btn('המשך לסקירה','group-review','primary')}</div></section><aside class="card"><div class="card-head"><h2>חברי הקבוצה</h2><span class="pill">2</span></div><div class="pad">${person('נועה לוי','נל','מנהלת') }<div class="section-gap">${person('יעל ברק','יב','רכזת')}</div><div class="section-gap">${note('לפני השמירה תוצג רשימת האנשים שהגישה שלהם תשתנה.')}</div></div></aside></div>`,
